        when(dimensionUserService.createDelete()).thenReturn(mockDelete);

        when(dimensionUserService.queryPager(any(QueryParamEntity.class))).thenReturn(
                Mono.just(PagerResult.of(0, Collections.emptyList())));
        when(dimensionUserService.count(any(QueryParamEntity.class))).thenReturn(Mono.just(0));
        when(dimensionUserService.count(any(Mono.class))).thenReturn(Mono.just(0));

        SaveResult saveResult = SaveResult.of(1, 0);
        doReturn(Mono.just(saveResult)).when(dimensionUserService).save(any(Flux.class));
        doReturn(Mono.just(1)).when(dimensionUserService).insert(any(Mono.class));
