        ReactiveAuthenticationHolder.setSupplier(new ReactiveAuthenticationSupplier() {
            @Override
            public Mono<Authentication> get() { return Mono.just(testAuth); }
            @Override
            public Mono<Authentication> get(String userId) { return Mono.just(testAuth); }
        });

        WebFluxDimensionUserController controller = new WebFluxDimensionUserController();

