public class ReactiveUserTokenControllerTest {}
/**************TEST SETUP BEGIN*************/
@Before
public void setup(){
        tokenManager = mock(UserTokenManager.class);
        authManager = mock(ReactiveAuthenticationManager.class);

        SimpleUser user = new SimpleUser();
        user.setId("user-1");
        user.setUsername("admin");
        user.setName("Admin");
        testAuth = new SimpleAuthentication();
        testAuth.setUser(user);
        testAuth.setPermissions(Collections.emptyList());

        ReactiveAuthenticationHolder.setSupplier(new ReactiveAuthenticationSupplier() {
            @Override
            public Mono<Authentication> get() { return Mono.just(testAuth); }
            @Override
            public Mono<Authentication> get(String userId) { return Mono.just(testAuth); }
        });

        ReactiveUserTokenController controller = new ReactiveUserTokenController();

        // Pass mocks BEFORE controller so they are registered as singletons
        // before Spring calls autowireBean(controller). The @Autowired @Lazy setters
        // inject lazy proxies that resolve to these registered singletons at call time.
        webTestClient = WebTestClient
                .bindToController(tokenManager, authManager, controller)
                .build();
    }
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
public void testGetByToken_notFound(){
        when(tokenManager.getByToken("unknown")).thenReturn(Mono.empty());

        webTestClient.get()
                .uri("/user-token/token/unknown")
                .exchange()
                .expectStatus().isOk()
                .expectBody().isEmpty();
    }
/**************TEST METHOD END*************/
/**************TEST TEARDOWN BEGIN*************/
@After
public void cleanup(){
        ReactiveAuthenticationHolder.setSupplier(new ReactiveAuthenticationSupplier() {
            @Override
            public Mono<Authentication> get() { return Mono.empty(); }
            @Override
            public Mono<Authentication> get(String userId) { return Mono.empty(); }
        });
    }
/**************TEST TEARDOWN END*************/


