@Before
public void setup(){
        tokenManager = mock(UserTokenManager.class);
        authManager = mock(ReactiveAuthenticationManager.class);

        SimpleUser user = new SimpleUser();
        user.setId("user-1");
        user.setUsername("admin");
        user.setName("Admin");
        testAuth = new SimpleAuthentication();
        testAuth.setUser(user);
        testAuth.setPermissions(Collections.emptyList());

        ReactiveAuthenticationHolder.setSupplier(new ReactiveAuthenticationSupplier() {
            @Override
            public Mono<Authentication> get() { return Mono.just(testAuth); }
