                .bindToController(authManager, controller)
                .build();

        ReactiveAuthenticationHolder.setSupplier(new ReactiveAuthenticationSupplier() {
            @Override
            public Mono<Authentication> get() { return Mono.just(testAuth); }
            @Override
            public Mono<Authentication> get(String userId) { return Mono.just(testAuth); }
        });
    }
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
public void testLogin_emptyBody_returnsError(){
        webTestClient.post()
                .uri("/authorize/login")
                .contentType(MediaType.APPLICATION_JSON)
                .bodyValue(Map.of("username", "", "password", ""))
                .exchange()
                .expectStatus().is5xxServerError();
    }
